
import {
  defineComponent,
  PropType,
  reactive,
  ref,
} from 'vue';
import {
  AjaxHelper,
  ContentBlock,
  NotificationsStore,
  translate,
} from 'CoreHome';
import { Field, SaveButton } from 'CorePluginsAdmin';

export interface UnitOption {
  key: string;
  value: string;
}

export interface UnitField {
  quantity: string;
  title: string;
  description: string;
  options: UnitOption[];
}

/**
 * Units in which the weather values of a site are displayed. Rendered on the Weather
 * page of the Websites administration, the site is chosen with the site selector of the page.
 */
export default defineComponent({
  name: 'ManageUnits',
  components: {
    ContentBlock,
    Field,
    SaveButton,
  },
  props: {
    idSite: {
      type: [Number, String],
      required: true,
    },
    fields: {
      type: Array as PropType<UnitField[]>,
      required: true,
    },
    units: {
      type: Object as PropType<Record<string, string>>,
      required: true,
    },
  },
  setup(props) {
    const values = reactive<Record<string, string>>({ ...props.units });
    const isSaving = ref(false);

    const save = () => {
      isSaving.value = true;

      AjaxHelper.post(
        { method: 'WeatherReports.setSiteUnits' },
        {
          idSite: props.idSite,
          temperature: values.temperature,
          precipitation: values.precipitation,
          pressure: values.pressure,
          visibility: values.visibility,
          windSpeed: values.wind,
        },
      ).then(() => {
        NotificationsStore.show({
          message: translate('General_YourChangesHaveBeenSaved'),
          context: 'success',
          type: 'toast',
          id: 'weatherReportsUnitsSaved',
        });
      }).finally(() => {
        isSaving.value = false;
      });
    };

    return {
      translate,
      values,
      isSaving,
      save,
    };
  },
});
